  app.querySelector('#join-test').onclick=()=>{joinResults=evaluateMatches(joinSelections);if(joinResults.every(item=>item.correct)){if(!completed.includes(active.id))completed.push(active.id);save();}renderJoin();app.querySelector('.result').scrollIntoView({block:'nearest'});app.querySelector('#return').focus();};
  if(joinResults)app.querySelector('#return').onclick=renderHome;
