  app.querySelector('#catalog-test').onclick=()=>{catalogResults=evaluateQuery(catalogFilters);if(catalogResults.every(item=>item.correct)){if(!completed.includes(active.id)) completed.push(active.id);save();}renderCatalog();app.querySelector('.result').scrollIntoView({block:'nearest'});app.querySelector('#return').focus();};
  if(catalogResults) app.querySelector('#return').onclick=renderHome;
